#fsd_btn_gallery {
  background-image: linear-gradient(#42A1EC, #0070C9) !important;
  background-color: linear-gradient(#42A1EC, #0070C9) !important;
  background: linear-gradient(#42A1EC, #0070C9) !important;
  border: 1px solid #0077CC;
  border-radius: 4px;
  box-sizing: border-box;
  color: #FFFFFF;
  cursor: pointer;
  direction: ltr;
  display: block;
  font-family: "SF Pro Text","SF Pro Icons","AOS Icons","Helvetica Neue",Helvetica,Arial,sans-serif;
  font-size: 17px;
  font-weight: 400;
  letter-spacing: -.022em;
  line-height: 1.47059;
  min-width: 30px;
  overflow: visible;
  padding: 4px 15px;
  text-align: center;
  vertical-align: baseline;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
  white-space: nowrap;
}

#fsd_btn_gallery:disabled {
  cursor: default;
  opacity: .3;
}

#fsd_btn_gallery:hover {
  background-image: linear-gradient(#51A9EE, #147BCD);
  border-color: #1482D0;
  text-decoration: none;
}

#fsd_btn_gallery:active {
  background-image: linear-gradient(#3D94D9, #0067B9);
  border-color: #006DBC;
  outline: none;
}

#fsd_btn_gallery:focus {
  box-shadow: rgba(131, 192, 253, 0.5) 0 0 0 3px;
  outline: none;
}

if (f._checked) {
  var e1 = (f._language == 'v' ? 'Trường <span class="Highlight">{0}</span> không hợp lệ.' : 'Invalid <span class="Highlight">{0}</span>.');
  var arrFields = ['mail_to', 'mail_cc', 'mail_bcc'];
  for (var i = 0; i < arrFields.length; i++) {
    if !(checkValidEmail$Test(f, arrFields[i], true)) {
      e1 = String.format(e1, f.getItem(arrFields[i]).field.HeaderText);
      $func.hideWait(id);
